t.Run("J02_R04_R10_R11_assignment_notification_scope", func(t *testing.T) {
	ticket := createTicket(t, agentA, "bf-j02-create-v1", "BF-J02-assignment")
	id := recordID(t, ticket)
	status, response := runAction(t, manager, id, "ticket.assign", map[string]any{"request_id": "bf-j02-assign-v1", "assignee_user_id": agentBIdentity})
	require2xx(t, "manager assignment", status, response)
	status, response = runAction(t, manager, id, "ticket.assign", map[string]any{"request_id": "bf-j02-assign-v1", "assignee_user_id": agentBIdentity})
	require2xx(t, "manager assignment replay", status, response)

	status, assigned, raw := getRecord(t, agentB, "ticket", id)
	require2xx(t, "new assignee detail", status, raw)
	if got, _ := recordData(t, assigned)["assignee_user_id"].(string); got != agentBIdentity {
		t.Fatalf("durable assignee=%q, want %q", got, agentBIdentity)
	}
	status, _, raw = getRecord(t, agentA, "ticket", id)
	requireDenied(t, "former assignee detail", status, raw)

	status, response = requestJSON(t, agentB, http.MethodPatch, "/objects/ticket/records/"+url.PathEscape(id), map[string]any{"data": map[string]any{"title": "BF-J02-updated-by-assignee", "priority": "urgent"}}, nil)
	status, response = requestJSON(t, agentB, http.MethodPatch, "/objects/ticket/records/"+url.PathEscape(id), map[string]any{"data": map[string]any{"title": "BF-J02-updated-by-assignee", "priority": "urgent"}}, map[string]string{"Idempotency-Key": "bf-j02-update-v1"})
	require2xx(t, "assignee field update", status, response)
	status, managerRead, raw := getRecord(t, manager, "ticket", id)
	require2xx(t, "manager assignment read-back", status, raw)
	if got, _ := recordData(t, managerRead)["title"].(string); got != "BF-J02-updated-by-assignee" {
		t.Fatalf("assignee update was not durable: %q", got)
	}

	status, notifications := requestJSON(t, agentB, http.MethodGet, "/business/notifications", nil, nil)
	require2xx(t, "recipient Inbox", status, notifications)
	if !jsonContainsString(notifications, id) || !jsonContainsString(notifications, "ticket.assigned") {
		t.Fatalf("recipient Inbox lacks the assignment notification for the target ticket")
	}
	status, formerInbox := requestJSON(t, agentA, http.MethodGet, "/business/notifications", nil, nil)
	require2xx(t, "former assignee Inbox", status, formerInbox)
	if jsonContainsString(formerInbox, id) && jsonContainsString(formerInbox, "ticket.assigned") {
		t.Fatalf("assignment notification leaked to the former assignee")
	}
})
	if data["content"] != "First durable diagnostic note" || data["author_user_id"] != agentAIdentity {
		t.Fatalf("comment durable facts are incomplete: %+v", data)
	}

	status, response = runAction(t, agentB, id, "ticket.add_comment", map[string]any{"request_id": "bf-j04-comment-denied", "content": "must not persist"})
	requireDenied(t, "sibling-agent comment", status, response)
	status, response = requestJSON(t, agentA, http.MethodPatch, "/objects/ticket_comment/records/"+url.PathEscape(commentID), map[string]any{"data": map[string]any{"content": "mutated"}}, map[string]string{"Idempotency-Key": "bf-j04-comment-update-denied"})
	requireDenied(t, "comment update", status, response)
	status, response = requestJSON(t, agentA, http.MethodDelete, "/objects/ticket_comment/records/"+url.PathEscape(commentID), nil, map[string]string{"Idempotency-Key": "bf-j04-comment-delete-denied"})
	requireDenied(t, "comment delete", status, response)
	status, commentAfter, raw := getRecord(t, agentA, "ticket_comment", commentID)
	require2xx(t, "comment unchanged read-back", status, raw)
	after, _ := json.Marshal(commentAfter)
	if string(after) != string(commentBefore) {
		t.Fatalf("denied comment mutations changed durable state")
	}
})

