func sessions(t *testing.T) (apiClient, apiClient, apiClient) {
	t.Helper()
	origin, password, workspace := runtimeConfig(t)
	return login(t, origin, workspace, agentAIdentity, password),
		login(t, origin, workspace, agentBIdentity, password),
		login(t, origin, workspace, managerIdentity, password)
}

func require2xx(t *testing.T, operation string, status int, response any) {
	t.Helper()
	if status < 200 || status >= 300 {
		t.Fatalf("%s returned %d (%s)", operation, status, findString(response, "error", "code"))
	}
}

func requireDenied(t *testing.T, operation string, status int, response any) {
	t.Helper()
	if status != http.StatusForbidden && status != http.StatusNotFound {
		t.Fatalf("%s expected scope/permission denial, got %d (%s)", operation, status, findString(response, "error", "code"))
	}
}

func asMap(t *testing.T, value any) map[string]any {
	t.Helper()
	if result, ok := value.(map[string]any); ok {
		return result
	}
	t.Fatalf("expected JSON object, got %T", value)
	return nil
}

func unwrapRecord(t *testing.T, value any) map[string]any {
	t.Helper()
	object := asMap(t, value)
	if record, ok := object["record"].(map[string]any); ok {
		return record
	}
	if _, hasID := object["id"]; hasID {
		return object
	}
	for _, child := range object {
		if candidate, ok := child.(map[string]any); ok {
			if _, hasID := candidate["id"]; hasID {
				if _, hasData := candidate["data"]; hasData {
					return candidate
				}
			}
		}
	}
	t.Fatalf("response contains no record")
	return nil
}

func recordID(t *testing.T, record map[string]any) string {
	t.Helper()
	id, _ := record["id"].(string)
	if id == "" {
		t.Fatalf("record has no id: %+v", record)
	}
	return id
}

func recordData(t *testing.T, record map[string]any) map[string]any {
	t.Helper()
	data, ok := record["data"].(map[string]any)
	if !ok {
		t.Fatalf("record has no data object: %+v", record)
	}
	return data
}

func getRecord(t *testing.T, client apiClient, objectKey, id string) (int, map[string]any, any) {
	t.Helper()
	status, response := requestJSON(t, client, http.MethodGet, "/objects/"+url.PathEscape(objectKey)+"/records/"+url.PathEscape(id), nil, nil)
	if status < 200 || status >= 300 {
		return status, nil, response
	}
	return status, unwrapRecord(t, response), response
}

func createTicket(t *testing.T, client apiClient, key, title string) map[string]any {
	t.Helper()
	status, response := requestJSON(t, client, http.MethodPost, "/objects/ticket/records", map[string]any{"data": map[string]any{
		"title": title, "description": "business-flow precondition", "priority": "high",
	}}, map[string]string{"Idempotency-Key": key})
	require2xx(t, "create ticket", status, response)
	return unwrapRecord(t, response)
}

func runAction(t *testing.T, client apiClient, recordID, actionKey string, payload map[string]any) (int, any) {
	t.Helper()
	idempotencyKey, _ := payload["request_id"].(string)
	if idempotencyKey == "" {
		idempotencyKey = "bf-action-" + strings.ReplaceAll(actionKey, ".", "-") + "-" + strconv.FormatInt(time.Now().UnixNano(), 10)
	}
	return requestJSON(t, client, http.MethodPost,
		"/objects/ticket/records/"+url.PathEscape(recordID)+"/actions/"+url.PathEscape(actionKey),
		map[string]any{"data": payload}, map[string]string{"Idempotency-Key": idempotencyKey})
}

func listRecords(t *testing.T, client apiClient, objectKey string, page, pageSize int) (int, []map[string]any, map[string]any, any) {
	t.Helper()
	path := "/objects/" + url.PathEscape(objectKey) + "/records?page=" + strconv.Itoa(page) + "&page_size=" + strconv.Itoa(pageSize)
	status, response := requestJSON(t, client, http.MethodGet, path, nil, nil)
	if status < 200 || status >= 300 {
		return status, nil, nil, response
	}
	pageObject := asMap(t, response)
	items, _ := pageObject["items"].([]any)
	records := make([]map[string]any, 0, len(items))
	for _, item := range items {
		if record, ok := item.(map[string]any); ok {
			records = append(records, record)
		}
	}
	return status, records, pageObject, response
}

func snapshot(t *testing.T, client apiClient, id string) string {
	t.Helper()
	status, record, response := getRecord(t, client, "ticket", id)
	require2xx(t, "read ticket snapshot", status, response)
	encoded, err := json.Marshal(record)
	if err != nil {
		t.Fatalf("encode snapshot: %v", err)
	}
	return string(encoded)
}

// J03 is the highest-risk real canary and must be executed before the broader suite.
func TestRuntimeHighestRiskJ03LifecycleScopeAuditAndRestartSeed(t *testing.T) {
	agentA, agentB, manager := sessions(t)
	runID := j03RunID()
	ticket := createTicket(t, agentA, "bf-j03-create-"+runID, "BF-J03-critical-restart-"+runID)
	id := recordID(t, ticket)

	beforeDenied := snapshot(t, manager, id)
	status, response := runAction(t, agentA, id, "ticket.close", map[string]any{"status": "closed"})
	requireDenied(t, "agent close", status, response)
	if after := snapshot(t, manager, id); after != beforeDenied {
		t.Fatalf("agent-close denial changed durable ticket state")
	}

	for _, step := range []struct {
		client apiClient
		action string
		status string
	}{
		{agentA, "ticket.start", "in_progress"},
		{agentA, "ticket.resolve", "resolved"},
		{manager, "ticket.reopen", "in_progress"},
		{agentA, "ticket.resolve", "resolved"},
		{manager, "ticket.close", "closed"},
	} {
		code, result := runAction(t, step.client, id, step.action, map[string]any{"status": step.status})
		require2xx(t, step.action, code, result)
		code, durable, raw := getRecord(t, manager, "ticket", id)
		require2xx(t, "durable lifecycle read-back", code, raw)
		if got, _ := recordData(t, durable)["status"].(string); got != step.status {
			t.Fatalf("%s durable status=%q, want %q", step.action, got, step.status)
		}
	}

	illegalTicket := createTicket(t, agentA, "bf-j03-invalid-create-"+runID, "BF-J03-invalid-new-to-closed-"+runID)
	illegalID := recordID(t, illegalTicket)
	illegalBefore := snapshot(t, manager, illegalID)
	status, response = runAction(t, manager, illegalID, "ticket.close", map[string]any{"status": "closed"})
	if status >= 200 && status < 300 {
		t.Fatalf("invalid new-to-closed transition unexpectedly succeeded")
	}
	if after := snapshot(t, manager, illegalID); after != illegalBefore {
		t.Fatalf("invalid transition changed durable ticket state")
	}

	status, _, response = getRecord(t, agentB, "ticket", id)
	requireDenied(t, "sibling-agent detail", status, response)

	auditPath := "/business/audit-events?object_key=ticket&record_id=" + url.QueryEscape(id) + "&page_size=100"
	status, audit := requestJSON(t, manager, http.MethodGet, auditPath, nil, nil)
	require2xx(t, "ticket audit read", status, audit)
	events := make(map[string]int)
	if items, ok := asMap(t, audit)["items"].([]any); ok {
		for _, item := range items {
			if entry, ok := item.(map[string]any); ok {
				if event, ok := entry["event"].(string); ok {
					events[event]++
				}
			}
		}
	}
	for _, required := range []string{"ticket.started", "ticket.resolved", "ticket.reopened", "ticket.closed"} {
		if events[required] == 0 {
			t.Fatalf("durable audit is missing %s: %+v", required, events)
		}
	}
}

func TestRuntimeBusinessFlowsJ01J02J04ToJ07(t *testing.T) {
	agentA, agentB, manager := sessions(t)

	t.Run("J01_R01_R03_R08_idempotent_creation", func(t *testing.T) {
		first := createTicket(t, agentA, "bf-j01-create-v1", "BF-J01-idempotent-create")
		second := createTicket(t, agentA, "bf-j01-create-v1", "BF-J01-idempotent-create")
		if recordID(t, first) != recordID(t, second) {
			t.Fatalf("same idempotency key created different tickets")
		}
		before := snapshot(t, manager, recordID(t, first))
		status, response := requestJSON(t, agentA, http.MethodPost, "/objects/ticket/records", map[string]any{"data": map[string]any{
			"title": "BF-J01-conflicting-payload", "priority": "urgent",
		}}, map[string]string{"Idempotency-Key": "bf-j01-create-v1"})
		if status >= 200 && status < 300 {
			t.Fatalf("same key with different payload unexpectedly succeeded")
		}
		if after := snapshot(t, manager, recordID(t, first)); after != before {
			t.Fatalf("idempotency conflict changed the original ticket")
		}
		_ = response
	})

	t.Run("J02_R04_R10_R11_assignment_notification_scope", func(t *testing.T) {
		ticket := createTicket(t, agentA, "bf-j02-create-v1", "BF-J02-assignment")
		id := recordID(t, ticket)
		status, response := runAction(t, manager, id, "ticket.assign", map[string]any{"request_id": "bf-j02-assign-v1", "assignee_user_id": agentBIdentity})
		require2xx(t, "manager assignment", status, response)
		status, response = runAction(t, manager, id, "ticket.assign", map[string]any{"request_id": "bf-j02-assign-v1", "assignee_user_id": agentBIdentity})
		require2xx(t, "manager assignment replay", status, response)

		status, assigned, raw := getRecord(t, agentB, "ticket", id)
		require2xx(t, "new assignee detail", status, raw)
		if got, _ := recordData(t, assigned)["assignee_user_id"].(string); got != agentBIdentity {
			t.Fatalf("durable assignee=%q, want %q", got, agentBIdentity)
		}
		status, _, raw = getRecord(t, agentA, "ticket", id)
		requireDenied(t, "former assignee detail", status, raw)

		status, response = requestJSON(t, agentB, http.MethodPatch, "/objects/ticket/records/"+url.PathEscape(id), map[string]any{"data": map[string]any{"title": "BF-J02-updated-by-assignee", "priority": "urgent"}}, map[string]string{"Idempotency-Key": "bf-j02-update-v1"})
		require2xx(t, "assignee field update", status, response)
		status, managerRead, raw := getRecord(t, manager, "ticket", id)
		require2xx(t, "manager assignment read-back", status, raw)
		if got, _ := recordData(t, managerRead)["title"].(string); got != "BF-J02-updated-by-assignee" {
			t.Fatalf("assignee update was not durable: %q", got)
		}

		status, notifications := requestJSON(t, agentB, http.MethodGet, "/business/notifications", nil, nil)
		require2xx(t, "recipient Inbox", status, notifications)
		if !jsonContainsString(notifications, id) || !jsonContainsString(notifications, "ticket.assigned") {
			t.Fatalf("recipient Inbox lacks the assignment notification for the target ticket")
		}
		status, formerInbox := requestJSON(t, agentA, http.MethodGet, "/business/notifications", nil, nil)
		require2xx(t, "former assignee Inbox", status, formerInbox)
		if jsonContainsString(formerInbox, id) && jsonContainsString(formerInbox, "ticket.assigned") {
			t.Fatalf("assignment notification leaked to the former assignee")
		}
	})

	t.Run("J04_R09_R10_append_only_comments", func(t *testing.T) {
		ticket := createTicket(t, agentA, "bf-j04-create-v1", "BF-J04-comments")
		id := recordID(t, ticket)
		status, response := runAction(t, agentA, id, "ticket.add_comment", map[string]any{"request_id": "bf-j04-comment-v1", "content": "First durable diagnostic note"})
		require2xx(t, "append comment", status, response)
		commentID := findString(response, "comment_id")
		if commentID == "" {
			t.Fatalf("append comment returned no comment identity")
		}
		status, comment, raw := getRecord(t, agentA, "ticket_comment", commentID)
		require2xx(t, "comment durable read-back", status, raw)
		commentBefore, _ := json.Marshal(comment)
		data := recordData(t, comment)
		if data["content"] != "First durable diagnostic note" || data["author_user_id"] != agentAIdentity {
			t.Fatalf("comment durable facts are incomplete: %+v", data)
		}

		status, response = runAction(t, agentB, id, "ticket.add_comment", map[string]any{"request_id": "bf-j04-comment-denied", "content": "must not persist"})
		requireDenied(t, "sibling-agent comment", status, response)
		status, response = requestJSON(t, agentA, http.MethodPatch, "/objects/ticket_comment/records/"+url.PathEscape(commentID), map[string]any{"data": map[string]any{"content": "mutated"}}, map[string]string{"Idempotency-Key": "bf-j04-comment-update-denied"})
		requireDenied(t, "comment update", status, response)
		status, response = requestJSON(t, agentA, http.MethodDelete, "/objects/ticket_comment/records/"+url.PathEscape(commentID), nil, map[string]string{"Idempotency-Key": "bf-j04-comment-delete-denied"})
		requireDenied(t, "comment delete", status, response)
		status, commentAfter, raw := getRecord(t, agentA, "ticket_comment", commentID)
		require2xx(t, "comment unchanged read-back", status, raw)
		after, _ := json.Marshal(commentAfter)
		if string(after) != string(commentBefore) {
			t.Fatalf("denied comment mutations changed durable state")
		}
	})

	t.Run("J05_R13_manager_status_report_agent_denied", func(t *testing.T) {
		status, report := requestJSON(t, manager, http.MethodPost, "/reports/ticket_status_counts/query", map[string]any{"parameters": map[string]any{}, "page_size": 4}, nil)
		require2xx(t, "manager status report", status, report)
		reportObject := asMap(t, report)
