					reportTotal += numericInt(measures["ticket_count"])
				}
			}
		}
		_, managerTickets, page, raw := listRecords(t, manager, "ticket", 1, 50)
		_ = managerTickets
		require2xx(t, "manager ticket list", http.StatusOK, raw)
		if exact := numericInt(page["total"]); exact > 0 && reportTotal != exact {
			t.Fatalf("report total=%d, authoritative ticket total=%d", reportTotal, exact)
		}
		status, denied := requestJSON(t, agentA, http.MethodPost, "/reports/ticket_status_counts/query", map[string]any{"parameters": map[string]any{}, "page_size": 4}, nil)
		requireDenied(t, "agent status report", status, denied)
	})

	t.Run("J06_R10_R14_R15_scope_pagination_menus", func(t *testing.T) {
		for role, expected := range map[string]struct {
			client apiClient
			keys   []string
		}{
			"agent":   {agentA, []string{"my_tickets"}},
			"manager": {manager, []string{"all_tickets", "ticket_reports"}},
		} {
			status, menu := requestJSON(t, expected.client, http.MethodGet, "/identity/effective-menus?surface=business_workspace", nil, nil)
			require2xx(t, role+" effective menus", status, menu)
			for _, key := range expected.keys {
				if !jsonContainsString(menu, key) {
					t.Fatalf("%s effective menus are missing %s", role, key)
				}
			}
			unexpected := []string{"all_tickets", "ticket_reports", "my_tickets"}
			for _, key := range unexpected {
				if !contains(expected.keys, key) && jsonContainsString(menu, key) {
					t.Fatalf("%s effective menus unexpectedly include %s", role, key)
				}
			}
		}

		_, first, firstPage, firstRaw := listRecords(t, manager, "ticket", 1, 1)
		require2xx(t, "bounded first page", http.StatusOK, firstRaw)
		if numericInt(firstPage["page_size"]) > 1 || len(first) > 1 {
			t.Fatalf("server page exceeded requested bound: %+v", firstPage)
		}
		_, second, _, secondRaw := listRecords(t, manager, "ticket", 2, 1)
		require2xx(t, "bounded second page", http.StatusOK, secondRaw)
		if len(first) == 1 && len(second) == 1 && recordID(t, first[0]) == recordID(t, second[0]) {
			t.Fatalf("stable pagination duplicated the boundary record")
		}

		_, ownTickets, _, ownRaw := listRecords(t, agentA, "ticket", 1, 50)
		require2xx(t, "agent scoped list", http.StatusOK, ownRaw)
