			data := recordData(t, record)
			if status, ok := data["status"].(string); ok {
				statuses[status] = true
			}
			if assignee, ok := data["assignee_user_id"].(string); ok {
				assignees[assignee] = true
			}
		}
		if len(statuses) < 3 || len(assignees) < 2 {
			t.Fatalf("seed diversity is incomplete: statuses=%v assignees=%v", sortedKeys(statuses), sortedKeys(assignees))
		}
	})
}

