func TestRuntimeRestartCanaryJ03(t *testing.T) {
	_, _, manager := sessions(t)
	title := "BF-J03-critical-restart-" + j03RunID()
	_, records, _, raw := listRecords(t, manager, "ticket", 1, 50)
	require2xx(t, "post-restart manager list", http.StatusOK, raw)
	var target map[string]any
	for _, record := range records {
		if recordData(t, record)["title"] == title {
			target = record
			break
		}
	}
	if target == nil {
		t.Fatalf("post-restart list is missing the critical J03 ticket")
	}
	if recordData(t, target)["status"] != "closed" {
		t.Fatalf("post-restart critical state=%v, want closed", recordData(t, target)["status"])
	}
	id := recordID(t, target)
	status, audit := requestJSON(t, manager, http.MethodGet, "/business/audit-events?object_key=ticket&record_id="+url.QueryEscape(id)+"&page_size=100", nil, nil)
