func j03RunID() string {
	runID := strings.TrimSpace(os.Getenv("DOMAINRY_J03_RUN_ID"))
	if runID == "" {
		return "default"
	}
	return runID
}

func jsonContainsString(value any, wanted string) bool {
	switch typed := value.(type) {
	case string:
		return typed == wanted
	case map[string]any:
		for _, child := range typed {
			if jsonContainsString(child, wanted) {
				return true
			}
		}
	case []any:
		for _, child := range typed {
			if jsonContainsString(child, wanted) {
				return true
			}
		}
	}
	return false
}

func numericInt(value any) int {
	switch typed := value.(type) {
	case float64:
		return int(typed)
	case json.Number:
		integer, _ := typed.Int64()
		return int(integer)
	case string:
		integer, _ := strconv.Atoi(typed)
		return integer
	case int:
		return typed
	}
	return 0
}

func contains(values []string, wanted string) bool {
	for _, value := range values {
		if value == wanted {
			return true
		}
	}
	return false
}

func sortedKeys(values map[string]bool) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

